export interface FastifyRequest {
  params: unknown;
  query: unknown;
  body: unknown;
}

export interface FastifyReply {
  send(payload?: unknown): FastifyReply;
}

export type RouteHandlerMethod = (
  request: FastifyRequest,
  reply: FastifyReply,
) => unknown | Promise<unknown>;

export interface RegisterOptions {
  prefix?: string;
}

export interface FastifyInstance {
  get(path: string, handler: RouteHandlerMethod): FastifyInstance;
  register(
    plugin: (instance: FastifyInstance, options: RegisterOptions) => void | Promise<void>,
    options?: RegisterOptions,
  ): FastifyInstance;
}

declare function fastify(): FastifyInstance;
export default fastify;
